import heapq

def compact_sstables(sstables: list[list[tuple]]) -> list[tuple]:
    # Group records across all SSTables by key
    latest_by_key = {}
    for sstable in sstables:
        for key, val, ts, is_tombstone in sstable:
            if key not in latest_by_key or ts > latest_by_key[key][2]:
                latest_by_key[key] = (key, val, ts, is_tombstone)

    # Filter out tombstones and sort by key ascending
    compacted = [
        (k, v, ts, False)
        for k, (key, v, ts, is_tombstone) in sorted(latest_by_key.items())
        if not is_tombstone
    ]
    return compacted
